display.text:
package images

import (
	"bytes"

	"github.com/yuin/goldmark"
	"github.com/yuin/goldmark/ast"
	"github.com/yuin/goldmark/parser"
	"github.com/yuin/goldmark/text"
	"github.com/yuin/goldmark/util"
)

type (
	imagesExtension struct {
		wrapStandAloneImageWithinParagraph bool
	}
)

const (
	// Used to signal to the rendering step that an image is used in a block context.
	// Dont's change this; the prefix must match the internalAttrPrefix in the root goldmark package.
	AttrIsBlock = "_h__isBlock"
	AttrOrdinal = "_h__ordinal"
)

func New(wrapStandAloneImageWithinParagraph bool) goldmark.Extender {
	return &imagesExtension{wrapStandAloneImageWithinParagraph: wrapStandAloneImageWithinParagraph}
}

func (e *imagesExtension) Extend(m goldmark.Markdown) {
	m.Parser().AddOptions(
		parser.WithASTTransformers(
			util.Prioritized(&Transformer{wrapStandAloneImageWithinParagraph: e.wrapStandAloneImageWithinParagraph}, 300),
		),
	)
}

type Transformer struct {
	wrapStandAloneImageWithinParagraph bool
}

// Transform transforms the provided Markdown AST.
func (t *Transformer) Transform(doc *ast.Document, reader text.Reader, pctx parser.Context) {
	var ordinal int
	ast.Walk(doc, func(node ast.Node, enter bool) (ast.WalkStatus, error) {
		if !enter {
			return ast.WalkContinue, nil
		}

		if n, ok := node.(*ast.Image); ok {
			parent := n.Parent()
			n.SetAttributeString(AttrOrdinal, ordinal)
			ordinal++

			if !t.wrapStandAloneImageWithinParagraph {
				isBlock := parent.ChildCount() == 1
				if isBlock {
					n.SetAttributeString(AttrIsBlock, true)
				}

				if isBlock && parent.Kind() == ast.KindParagraph {
					TransferImageParentAttributes(parent.Attributes(), func(name []byte, value any) {
						n.SetAttribute(name, value)
					})
					grandParent := parent.Parent()
					grandParent.ReplaceChild(grandParent, parent, n)
				}
			}

		}

		return ast.WalkContinue, nil
	})
}

var (
	transferImageParentAttributes = defaultTransferImageParentAttributes
	filterInternalHookAttributes  = defaultFilterInternalHookAttributes
	coordinateRenderHookLookup    = defaultCoordinateRenderHookLookup
)

type TransferImageParentAttributesFunc func(parentAttrs []ast.Attribute, set func(name []byte, value any))
type FilterInternalHookAttributesFunc func(attrs []ast.Attribute) []ast.Attribute
type CoordinateRenderHookLookupFunc func(kind, name string)

func InstallTemplateCoordinator(transfer TransferImageParentAttributesFunc, filter FilterInternalHookAttributesFunc, coord CoordinateRenderHookLookupFunc) {
	if transfer != nil {
		transferImageParentAttributes = transfer
	}
	if filter != nil {
		filterInternalHookAttributes = filter
	}
	if coord != nil {
		coordinateRenderHookLookup = coord
	}
}

func TransferImageParentAttributes(parentAttrs []ast.Attribute, set func(name []byte, value any)) {
	transferImageParentAttributes(parentAttrs, set)
}

func FilterInternalHookAttributes(attrs []ast.Attribute) []ast.Attribute {
	return filterInternalHookAttributes(attrs)
}

func CoordinateRenderHookTemplate(kind, name string) {
	coordinateRenderHookLookup(kind, name)
}

func defaultTransferImageParentAttributes(parentAttrs []ast.Attribute, set func(name []byte, value any)) {
	for _, attr := range parentAttrs {
		set(attr.Name, attr.Value)
	}
}

func defaultFilterInternalHookAttributes(attrs []ast.Attribute) []ast.Attribute {
	n := 0
	for _, x := range attrs {
		if !bytes.HasPrefix(x.Name, []byte("_h__")) {
			attrs[n] = x
			n++
		}
	}
	return attrs[:n]
}

func defaultCoordinateRenderHookLookup(kind, name string) {}

